    stage_id smallint NOT NULL,
    context_id bigint NOT NULL,
    include boolean DEFAULT false NOT NULL,
    due_interval character varying(255),
    type character varying(255) DEFAULT '1'::character varying NOT NULL,
    restrict_to_user_groups boolean DEFAULT false NOT NULL,
    key character varying(255),
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    CONSTRAINT edit_task_templates_due_interval_check CHECK (((due_interval)::text = ANY ((ARRAY['P1W'::character varying, 'P2W'::character varying, 'P3W'::character varying, 'P4W'::character varying, 'P1M'::character varying, 'P1M15D'::character varying, 'P2M'::character varying, 'P2M15D'::character varying, 'P3M'::character varying])::text[]))),
    CONSTRAINT edit_task_templates_type_check CHECK (((type)::text = ANY ((ARRAY['1'::character varying, '2'::character varying])::text[])))
);


